fn run_copy(bin: &str, global: &GlobalOptions, args: &[String]) -> i32 {
    let mut index = 0usize;
    let mut positional = Vec::new();

    while index < args.len() {
        let current = &args[index];
        match current.as_str() {
            "-h" | "--help" => {
                print_copy_help(bin);
                return 0;
            }
            "-V" | "--version" => {
                print_subcommand_version(bin, "copy");
                return 0;
            }
            _ if current.starts_with('-') && current != "-" => {
                return parse_error(
                    &format!(
                        "Found argument '{}' which wasn't expected, or isn't valid in this context",
                        current
                    ),
                    &format!("    {} copy <from-alias> <to-alias>", bin),
                )
            }
            _ => {
                positional.push(current.clone());
                index += 1;
            }
        }
    }

    if positional.len() < 2 {
        let mut missing = Vec::new();
        if positional.is_empty() {
            missing.push("<from-alias>");
            missing.push("<to-alias>");
        } else {
            missing.push("<to-alias>");
        }
        return missing_required_error(
            &missing,
            &format!("    {} copy <from-alias> <to-alias>", bin),
        );
    }
    if positional.len() > 2 {
        return parse_error(
            &format!(
                "Found argument '{}' which wasn't expected, or isn't valid in this context",
                positional[2]
            ),
            &format!("    {} copy <from-alias> <to-alias>", bin),
        );
    }

    let config_path = match resolve_read_path(global) {
        Ok(path) => path,
        Err(error) => return fail(error),
    };
    let mut config = match read_config(&config_path) {
        Ok(config) => config,
        Err(error) => return fail(error),
    };

    let from_alias = &positional[0];
    let to_alias = &positional[1];
    let script = match config.scripts.get(from_alias) {
        Some(script) => script.clone(),
        None => {
            return fail(CliError::new(format!(
                "AliasNotFound: No script found by alias {}",
                from_alias
            )))
        }
    };

    if config.scripts.contains_key(to_alias) {
        return fail(CliError::new(format!("AliasAlreadyExists:  {}", to_alias)));
    }

    config.scripts.insert(to_alias.clone(), script);
    if let Err(error) = write_config(&config_path, &config) {
        return fail(error);
    }

    println!("Copy from alias {} to new alias {}", from_alias, to_alias);
    0
}

fn run_edit(bin: &str, global: &GlobalOptions, args: &[String]) -> i32 {
    let alias = match parse_single_alias_subcommand(bin, "edit", args) {
        Ok(ControlAlias::Help) => {
            print_edit_help(bin);
            return 0;
        }
        Ok(ControlAlias::Version) => {
            print_subcommand_version(bin, "edit");
            return 0;
        }
        Ok(ControlAlias::Alias(alias)) => alias,
        Err(code) => return code,
    };

    let config_path = match resolve_read_path(global) {
        Ok(path) => path,
        Err(error) => return fail(error),
    };
    let mut config = match read_config(&config_path) {
        Ok(config) => config,
        Err(error) => return fail(error),
    };

    let current = match lookup_script_with_empty_message_mut(&mut config, &alias) {
        Ok(script) => script,
        Err(error) => return fail(error),
    };

    let updated = match open_editor(current.command.clone()) {
        Ok(command) => command,
        Err(error) => return fail(CliError::new(error)),
    };
    current.command = updated;

    if let Err(error) = write_config(&config_path, &config) {
        return fail(error);
    }

    println!("Edited {}", alias);
    0
}

