            if tail[index] == "--" {
                raw_mode = true;
                index += 1;
                continue;
            }

            match parse_global_step(&tail[index..], &mut state, true) {
                ParseStep::Consumed(consumed) => {
                    index += consumed;
                    continue;
                }
                ParseStep::Signal(GlobalToken::Help) => {
                    print_top_help_long(bin);
                    return 0;
                }
                ParseStep::Signal(GlobalToken::Version) => {
                    print_top_version();
                    return 0;
                }
                ParseStep::Signal(GlobalToken::NotGlobal) => {
                    script_args.push(tail[index].clone());
                    index += 1;
                    script_args.extend_from_slice(&tail[index..]);
                    break;
                }
                ParseStep::UnknownOption(option) => {
                    return parse_error(
                        &format!(
                            "Found argument '{}' which wasn't expected, or isn't valid in this context",
                            option
                        ),
                        &top_usage_for_flags(bin, &state.global),
                    );
                }
                ParseStep::MissingValue(flag) => {
                    return parse_error(
                        &format!(
                            "The argument '{}' requires a value but none was supplied",
                            flag
                        ),
                        &top_usage_for_flags(bin, &state.global),
                    );
                }
            }
        } else {
            script_args.extend_from_slice(&tail[index..]);
            break;
        }
    }

    let command = match command {
