fn parse_global_step(args: &[String], state: &mut GlobalState, alias_phase: bool) -> ParseStep {
    if args.is_empty() {
        return ParseStep::Signal(GlobalToken::NotGlobal);
    }

    let current = &args[0];
    match current.as_str() {
        "-h" | "--help" => return ParseStep::Signal(GlobalToken::Help),
        "-V" | "--version" => return ParseStep::Signal(GlobalToken::Version),
        "-v" | "--verbose" => {
            if state.global.verbose {
                state.repeated_verbose = true;
            } else {
                state.global.verbose = true;
            }
            return ParseStep::Consumed(1);
        }
        "-c" | "--config-file" => {
            if args.len() < 2 {
                return ParseStep::MissingValue("--config-file <path>".to_string());
            }
            set_cli_config_path(state, args[1].clone());
            return ParseStep::Consumed(2);
        }
        _ => {}
    }

    if let Some(value) = current.strip_prefix("--config-file=") {
        set_cli_config_path(state, value.to_string());
        return ParseStep::Consumed(1);
    }

    if current.starts_with('-') && current != "-" {
        if current.starts_with("--") {
            return ParseStep::UnknownOption(current.clone());
        }

        let short = &current[1..];
        let mut consumed = 1usize;
        let mut chars = short.chars().peekable();
        while let Some(ch) = chars.next() {
            match ch {
                'h' => return ParseStep::Signal(GlobalToken::Help),
                'V' => return ParseStep::Signal(GlobalToken::Version),
                'v' => {
                    if state.global.verbose {
                        state.repeated_verbose = true;
                    } else {
                        state.global.verbose = true;
                    }
                }
                'c' => {
                    let rest: String = chars.collect();
                    if !rest.is_empty() {
                        set_cli_config_path(state, rest);
                        return ParseStep::Consumed(consumed);
                    }
                    if args.len() < 2 {
                        return ParseStep::MissingValue("--config-file <path>".to_string());
                    }
                    set_cli_config_path(state, args[1].clone());
                    consumed = 2;
                    return ParseStep::Consumed(consumed);
                }
                _ => return ParseStep::UnknownOption(current.clone()),
            }
        }
        return ParseStep::Consumed(consumed);
    }

    if alias_phase {
        ParseStep::Signal(GlobalToken::NotGlobal)
    } else {
        ParseStep::Signal(GlobalToken::NotGlobal)
    }
}

fn set_cli_config_path(state: &mut GlobalState, path: String) {
    if state.global.config_from_cli {
        state.repeated_config = true;
    } else {
        state.global.config_path = Some(path);
        state.global.config_from_cli = true;
    }
}

fn subcommand_from_name(name: &str) -> Option<Subcommand> {
    match name {
        "add" => Some(Subcommand::Add),
        "config-init" | "init" => Some(Subcommand::ConfigInit),
        "copy" | "cp" => Some(Subcommand::Copy),
        "edit" => Some(Subcommand::Edit),
        "help" => Some(Subcommand::Help),
        "list" | "ls" => Some(Subcommand::List),
        "move" | "mv" | "rename" => Some(Subcommand::Move),
        "remove" | "rm" => Some(Subcommand::Remove),
        "run" => Some(Subcommand::Run),
        "show" => Some(Subcommand::Show),
        _ => None,
    }
}

fn canonical_subcommand_name(subcommand: Subcommand) -> &'static str {
    match subcommand {
        Subcommand::Add => "add",
        Subcommand::ConfigInit => "config-init",
        Subcommand::Copy => "copy",
        Subcommand::Edit => "edit",
        Subcommand::Help => "help",
        Subcommand::List => "list",
        Subcommand::Move => "move",
        Subcommand::Remove => "remove",
        Subcommand::Run => "run",
        Subcommand::Show => "show",
    }
}

fn subcommand_suggestion(name: &str, explicit_end: bool) -> Option<String> {
    if explicit_end {
        if let Some(command) = subcommand_from_name(name) {
            return Some(canonical_subcommand_name(command).to_string());
        }
    }

    let candidates = [
        "add",
        "config-init",
        "copy",
        "edit",
        "help",
        "list",
        "move",
        "remove",
        "run",
        "show",
    ];

    let mut best: Option<(&str, i32)> = None;
    for candidate in candidates {
        let prefix = common_prefix_len(name, candidate) as i32;
        let distance = levenshtein(name, candidate) as i32;
        let eligible = prefix >= 3 || distance <= 1 || candidate.starts_with(name) && name.len() >= 2;
        if !eligible {
            continue;
        }
        let score = prefix * 10 - distance * 2 - (name.len() as i32 - candidate.len() as i32).abs();
        match best {
            None => best = Some((candidate, score)),
            Some((_, best_score)) if score > best_score => best = Some((candidate, score)),
            _ => {}
        }
    }
    best.map(|(candidate, _)| candidate.to_string())
}

fn common_prefix_len(left: &str, right: &str) -> usize {
    left.chars()
        .zip(right.chars())
        .take_while(|(a, b)| a == b)
        .count()
}

fn levenshtein(left: &str, right: &str) -> usize {
    let left: Vec<char> = left.chars().collect();
    let right: Vec<char> = right.chars().collect();
    if left.is_empty() {
        return right.len();
    }
    if right.is_empty() {
        return left.len();
    }

    let mut previous: Vec<usize> = (0..=right.len()).collect();
    let mut current = vec![0usize; right.len() + 1];

    for (i, left_char) in left.iter().enumerate() {
        current[0] = i + 1;
        for (j, right_char) in right.iter().enumerate() {
            let cost = usize::from(left_char != right_char);
            current[j + 1] = (current[j] + 1)
                .min(previous[j + 1] + 1)
                .min(previous[j] + cost);
        }
        previous.clone_from(&current);
    }

    previous[right.len()]
}

fn top_usage_for_flags(bin: &str, global: &GlobalOptions) -> String {
    if !global.verbose && !global.config_from_cli {
        return full_top_usage(bin);
    }

    let mut usage = format!("    {} <alias>", bin);
    if global.config_from_cli {
        usage.push_str(" --config-file <path>");
    }
    if global.verbose {
        usage.push_str(" --verbose");
    }
    usage
}

fn full_top_usage(bin: &str) -> String {
    format!(
        "    {} [FLAGS] [OPTIONS] <alias> [args]...\n    {} [FLAGS] [OPTIONS] <SUBCOMMAND>",
        bin, bin
    )
}

