fn parse_toml_string(
    lines: &[&str],
    start_index: usize,
    value: &str,
    key_path: &str,
) -> Result<(String, usize), String> {
    if let Some(rest) = value.strip_prefix("'''") {
        return parse_multiline_literal_string(lines, start_index, rest);
    }
    if let Some(rest) = value.strip_prefix("\"\"\"") {
        return parse_multiline_basic_string(lines, start_index, rest);
    }
    if value.starts_with('\'') {
        if !value.ends_with('\'') || value.len() < 2 {
            return Err(format!("unterminated string for key `{}`", key_path));
        }
        return Ok((value[1..value.len() - 1].to_string(), start_index));
    }
    if value.starts_with('"') {
        if !value.ends_with('"') || value.len() < 2 {
            return Err(format!("unterminated string for key `{}`", key_path));
        }
        return Ok((parse_basic_string(&value[1..value.len() - 1])?, start_index));
    }
    if value.starts_with('[') {
        return Err(format!(
            "invalid type: array, expected a string for key `{}`",
            key_path
        ));
    }
    if value == "true" || value == "false" {
        return Err(format!(
            "invalid type: boolean `{}`, expected a string for key `{}`",
            value, key_path
        ));
    }
    if value.parse::<i64>().is_ok() {
        return Err(format!(
            "invalid type: integer `{}`, expected a string for key `{}`",
            value, key_path
        ));
    }

    Err(format!("invalid value `{}` for key `{}`", value, key_path))
}

fn parse_multiline_literal_string(
    lines: &[&str],
    start_index: usize,
    rest: &str,
) -> Result<(String, usize), String> {
    if let Some(end) = rest.find("'''") {
        return Ok((rest[..end].to_string(), start_index));
    }

    let mut value = String::new();
    if !rest.is_empty() {
        value.push_str(rest);
        value.push('\n');
    }

    let mut index = start_index + 1;
    while index < lines.len() {
        let line = lines[index];
        if let Some(end) = line.find("'''") {
            value.push_str(&line[..end]);
            return Ok((value, index));
        }
        value.push_str(line);
        value.push('\n');
        index += 1;
    }

    Err(format!(
        "unterminated multi-line string at line {}",
        start_index + 1
    ))
}

