    while index < lines.len() {
        let line = lines[index];
        if let Some(end) = line.find("\"\"\"") {
            value.push_str(&line[..end]);
            return Ok((parse_basic_string(&value)?, index));
        }
        value.push_str(line);
        value.push('\n');
        index += 1;
    }

    Err(format!(
        "unterminated multi-line string at line {}",
        start_index + 1
    ))
}

fn parse_basic_string(raw: &str) -> Result<String, String> {
    let mut out = String::new();
    let mut chars = raw.chars();
    while let Some(ch) = chars.next() {
        if ch == '\\' {
            let escaped = chars.next().ok_or_else(|| "unterminated escape sequence".to_string())?;
            match escaped {
                'n' => out.push('\n'),
                'r' => out.push('\r'),
                't' => out.push('\t'),
                '\\' => out.push('\\'),
                '"' => out.push('"'),
                other => out.push(other),
            }
        } else {
            out.push(ch);
        }
    }
    Ok(out)
}

fn parse_toml_string_array(
    lines: &[&str],
    start_index: usize,
    value: &str,
    key_path: &str,
) -> Result<(Vec<String>, usize), String> {
    let trimmed = value.trim();
    if trimmed == "[]" {
        return Ok((Vec::new(), start_index));
    }
    if trimmed.starts_with('[') && trimmed.ends_with(']') {
        let inner = &trimmed[1..trimmed.len() - 1];
        if inner.trim().is_empty() {
            return Ok((Vec::new(), start_index));
        }
        return Ok((parse_inline_string_array(inner, key_path)?, start_index));
    }
    if trimmed.starts_with('[') {
        let mut values = Vec::new();
        let mut index = start_index + 1;
        while index < lines.len() {
            let item = lines[index].trim();
            if item == "]" {
                return Ok((values, index));
            }
            let item = item.strip_suffix(',').unwrap_or(item).trim();
            let (value, _) = parse_toml_string(lines, index, item, key_path)?;
            values.push(value);
            index += 1;
        }
        return Err(format!("unterminated array for key `{}`", key_path));
    }
    if trimmed.parse::<i64>().is_ok() {
        return Err(format!(
            "invalid type: integer `{}`, expected a sequence for key `{}`",
            trimmed, key_path
        ));
    }
    Err(format!(
        "invalid value `{}` for key `{}`",
        trimmed, key_path
    ))
}

fn parse_inline_string_array(raw: &str, key_path: &str) -> Result<Vec<String>, String> {
    let mut values = Vec::new();
    let mut current = String::new();
    let mut quote: Option<char> = None;
    let mut escape = false;
    for ch in raw.chars() {
        if let Some(delimiter) = quote {
            current.push(ch);
            if delimiter == '"' && escape {
                escape = false;
                continue;
            }
            if delimiter == '"' && ch == '\\' {
                escape = true;
                continue;
            }
            if ch == delimiter {
                quote = None;
            }
            continue;
        }

        match ch {
            '\'' | '"' => {
                quote = Some(ch);
                current.push(ch);
            }
            ',' => {
                let token = current.trim();
                if !token.is_empty() {
                    let (parsed, _) = parse_toml_string(&[], 0, token, key_path)?;
                    values.push(parsed);
                }
                current.clear();
            }
            _ => current.push(ch),
        }
    }
    let token = current.trim();
    if !token.is_empty() {
        let (parsed, _) = parse_toml_string(&[], 0, token, key_path)?;
        values.push(parsed);
    }
    Ok(values)
}

fn parse_raw_toml_value(lines: &[&str], start_index: usize, value: &str) -> Result<(String, usize), String> {
    let trimmed = value.trim();
    if let Some(rest) = trimmed.strip_prefix("'''") {
        if rest.contains("'''") {
            return Ok((trimmed.to_string(), start_index));
        }
        return collect_until(lines, start_index, "'''", trimmed);
    }
    if let Some(rest) = trimmed.strip_prefix("\"\"\"") {
        if rest.contains("\"\"\"") {
            return Ok((trimmed.to_string(), start_index));
        }
        return collect_until(lines, start_index, "\"\"\"", trimmed);
    }
    if trimmed.starts_with('[') && !trimmed.ends_with(']') {
        return collect_until(lines, start_index, "]", trimmed);
    }
    Ok((trimmed.to_string(), start_index))
}

fn collect_until(
    lines: &[&str],
    start_index: usize,
    terminator: &str,
    first_line: &str,
) -> Result<(String, usize), String> {
    let mut raw = first_line.to_string();
    let mut index = start_index + 1;
    while index < lines.len() {
        raw.push('\n');
        raw.push_str(lines[index]);
        if lines[index].contains(terminator) {
            return Ok((raw, index));
        }
        index += 1;
    }
    Err(format!(
        "unterminated value at line {}",
        start_index + 1
    ))
}

fn serialize_config(config: &Config) -> String {
    let mut out = String::new();

    if config.scripts.is_empty() {
        out.push_str("[scripts]\n\n");
    } else {
        for (alias, script) in &config.scripts {
            out.push_str("[scripts.");
            out.push_str(&format_table_key(alias));
            out.push_str("]\n");
            out.push_str("command = ");
            out.push_str(&format_toml_string(&script.command));
            out.push('\n');

            if let Some(description) = &script.description {
                out.push_str("description = ");
                out.push_str(&format_toml_string(description));
                out.push('\n');
            }
            if let Some(tags) = &script.tags {
                out.push_str("tags = ");
                out.push_str(&format_toml_string_array(tags));
                out.push('\n');
            }
            out.push('\n');
        }
    }

    out.push_str("[default]\n");
    for (key, raw_value) in &config.default {
        out.push_str(key);
        out.push_str(" = ");
        out.push_str(raw_value);
        out.push('\n');
    }

    out
}

fn format_table_key(key: &str) -> String {
    if key
        .chars()
        .all(|ch| ch.is_ascii_alphanumeric() || ch == '-' || ch == '_')
    {
        key.to_string()
    } else {
        format!("\"{}\"", escape_basic_string_for_write(key))
    }
}

fn format_toml_string(value: &str) -> String {
    if value.contains('\n') {
        if !value.contains("'''") {
            return format!("'''\n{}'''", value);
        }
        return format!("\"\"\"\n{}\"\"\"", escape_multiline_basic_string_for_write(value));
    }
    if !value.contains('\'') {
        return format!("'{}'", value);
    }
    format!("\"{}\"", escape_basic_string_for_write(value))
}

fn format_toml_string_array(values: &[String]) -> String {
    if values.is_empty() {
        return "[]".to_string();
    }
    if values.len() == 1 {
        return format!("[{}]", format_toml_string(&values[0]));
    }

    let mut out = String::from("[\n");
    for value in values {

    for value in values {
        out.push_str("    ");
        out.push_str(&format_toml_string(value));
        out.push_str(",\n");
    }
    out.push(']');
    out
}

fn escape_basic_string_for_write(value: &str) -> String {
    let mut out = String::new();
    for ch in value.chars() {
        match ch {
            '\\' => out.push_str("\\\\"),
            '"' => out.push_str("\\\""),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            other => out.push(other),
        }
    }
    out
}

fn escape_multiline_basic_string_for_write(value: &str) -> String {
    value.replace('\\', "\\\\").replace("\"\"\"", "\\\"\\\"\\\"")
}

fn lookup_script_with_empty_message<'a>(config: &'a Config, alias: &str) -> Result<&'a Script, CliError> {
    if config.scripts.is_empty() {
        return Err(CliError::new(
            "No scripts exist. Would you like to add a new script?",
        ));
    }

    config
        .scripts
        .get(alias)
        .ok_or_else(|| CliError::new(format!("AliasNotFound: No script found by alias {}", alias)))
}

fn lookup_script_with_empty_message_mut<'a>(
    config: &'a mut Config,
    alias: &str,
) -> Result<&'a mut Script, CliError> {
    if config.scripts.is_empty() {
        return Err(CliError::new(
            "No scripts exist. Would you like to add a new script?",
        ));
    }

    config
        .scripts
        .get_mut(alias)

fn read_config(path: &Path) -> Result<Config, CliError> {
    let raw = fs::read_to_string(path).map_err(|error| {
        CliError::new(format!(
            "Unable to read config from file {}: {} ",
            path.display(),
            error
        ))
    })?;

    parse_config(&raw).map_err(|error| {
        CliError::new(format!(
            "Unable to parse toml config from file {}: {}",
            path.display(),
            error
        ))
    })
}

fn write_config(path: &Path, config: &Config) -> Result<(), CliError> {
    let raw = serialize_config(config);
    fs::write(path, raw).map_err(|error| {
        CliError::new(format!(
            "Unable to write config to file {}: {}",
            path.display(),
            error
        ))
    })
}

